#!/usr/bin/env python3
"""Generates core/c515_ops.inc and core/c515_ops_decl_body.inc from MAME's mcs51 core (BSD-3-Clause).

    tools/port_c515.py <mame mcs51 folder>

The instruction bodies are MAME's, with its memory spaces replaced by the calls core/c515.h has.
"""
import pathlib, re, sys

src = pathlib.Path(sys.argv[1])
core = pathlib.Path(__file__).resolve().parent.parent / "core"
notice = ("// license:BSD-3-Clause\n// copyright-holders:Steve Ellenoff\n"
          "// Generated by tools/port_c515.py from MAME's src/devices/cpu/mcs51/mcs51ops.cpp. Do not edit.\n\n")

text = (src / "mcs51ops.cpp").read_text()
text = text[text.index("// # of oscillations each opcode requires"):]
text = text.replace("mcs51_cpu_device::", "C515::")
for old, new in [("m_program.read_byte(", "code("), ("m_idata.read_byte(", "iramR("), ("m_idata.write_byte(", "iramW("),
                 ("m_sfr.read_byte(", "sfrR("), ("m_sfr.write_byte(", "sfrW("),
                 ("m_xdata.read_byte(", "xdataR("), ("m_xdata.write_byte(", "xdataW("),
                 ("m_program.read_word(", "codeWord("),
                 ("m_internal_ram[", "m_iram[")]:
    text = text.replace(old, new)
text = re.sub(r"^\s*LOG\(.*\);.*\n", "", text, flags=re.M)
(core / "c515_ops.inc").write_text(notice + text)

head = (src / "i8051.h").read_text()
start, end = head.index("\tvoid acall(u8 r);"), head.index("\tvoid illegal(u8 r);") + len("\tvoid illegal(u8 r);")
(core / "c515_ops_decl_body.inc").write_text(notice + head[start:end] + "\n")
